import uuid
import time
import logging
from contextlib import asynccontextmanager

from fastapi import FastAPI, Request, Response, Depends, HTTPException
import httpx
import redis.asyncio as aioredis

from app.config import settings
from app.auth import verify_auth
from app.rate_limiter import RateLimiter
from app.proxy import proxy_request

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(name)s — %(message)s",
)
log = logging.getLogger("api-gateway")

# ── Shared clients (initialised in lifespan) ─────────────────────────────────
_redis: aioredis.Redis | None = None
_limiter: RateLimiter | None = None
_http: httpx.AsyncClient | None = None


@asynccontextmanager
async def lifespan(app: FastAPI):
    global _redis, _limiter, _http
    _redis = aioredis.from_url(f"redis://{settings.REDIS_HOST}:{settings.REDIS_PORT}")
    _limiter = RateLimiter(_redis)
    _http = httpx.AsyncClient(
        base_url=settings.PAYMENT_SWITCH_URL,
        timeout=settings.UPSTREAM_TIMEOUT,
    )
    log.info("api-gateway UP  upstream=%s  env=%s", settings.PAYMENT_SWITCH_URL, settings.ENV)
    yield
    await _redis.aclose()
    await _http.aclose()
    log.info("api-gateway DOWN")


app = FastAPI(title="IBTS API Gateway", version="1.0.0", lifespan=lifespan)


# ── Request-ID + access-log middleware ───────────────────────────────────────
@app.middleware("http")
async def access_log(request: Request, call_next):
    request.state.request_id = request.headers.get("X-Request-ID", str(uuid.uuid4()))
    t0 = time.perf_counter()
    response: Response = await call_next(request)
    latency_ms = round((time.perf_counter() - t0) * 1000, 1)
    log.info(
        "method=%s path=%s status=%s latency_ms=%s req_id=%s ip=%s",
        request.method, request.url.path, response.status_code,
        latency_ms, request.state.request_id, request.client.host,
    )
    response.headers["X-Request-ID"] = request.state.request_id
    response.headers["X-Latency-Ms"] = str(latency_ms)
    return response


# ── Health (no auth, no rate limit — used by Docker healthcheck) ─────────────
@app.get("/actuator/health", tags=["ops"])
async def health():
    return {"status": "UP", "service": "api-gateway"}


# ── Payment endpoints ─────────────────────────────────────────────────────────
@app.post("/api/v1/payments", tags=["payments"])
async def create_payment(request: Request, claims: dict = Depends(verify_auth)):
    await _enforce_ip_limit(request)

    # VPA-level throttle — parse debit_vpa from body if available
    try:
        import json
        body_json = json.loads(await request.body())
        vpa = body_json.get("debit_vpa", "")
        if vpa:
            allowed, _ = await _limiter.check_vpa(vpa)
            if not allowed:
                raise HTTPException(status_code=429, detail=f"Rate limit exceeded for VPA {vpa}")
    except (ValueError, KeyError):
        pass  # malformed JSON — let payment-switch return 422

    return await proxy_request(_http, request, "/api/v1/payments")


@app.get("/api/v1/payments/{txn_id}", tags=["payments"])
async def get_payment(txn_id: str, request: Request, claims: dict = Depends(verify_auth)):
    await _enforce_ip_limit(request)
    return await proxy_request(_http, request, f"/api/v1/payments/{txn_id}")


# ── Helpers ───────────────────────────────────────────────────────────────────
async def _enforce_ip_limit(request: Request):
    allowed, remaining = await _limiter.check_ip(request.client.host)
    if not allowed:
        raise HTTPException(
            status_code=429,
            detail="IP rate limit exceeded",
            headers={"Retry-After": str(settings.RL_WINDOW_SECONDS)},
        )
